mapper.select:
SELECT  FROM reservation
WHERE user_id = #{userId}
AND status = #{status}
AND start_at >= #{dateFrom}
AND start_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM reservation
WHERE user_id = #{userId}
AND status = #{status}
AND start_at >= #{dateFrom}
AND start_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)

SELECT  FROM reservation
WHERE seat_id = #{seatId}
  AND status IN ('RESERVED', 'IN_USE', 'LEFT_TEMP')
  AND start_at < #{endAt} AND end_at > #{startAt}
ORDER BY start_at

SELECT  FROM reservation
WHERE user_id = #{userId}
  AND status IN ('RESERVED', 'IN_USE', 'LEFT_TEMP')
  AND start_at < #{endAt} AND end_at > #{startAt}
ORDER BY start_at

SELECT r.* FROM reservation r
LEFT JOIN app_user u ON u.id = r.user_id

  AND u.account LIKE CONCAT(#{account}, '%')
  AND r.room_id = #{roomId}
  AND r.status = #{status}
  AND r.start_at >= #{dateFrom}
  AND r.start_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)

ORDER BY r.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM reservation r
LEFT JOIN app_user u ON u.id = r.user_id

  AND u.account LIKE CONCAT(#{account}, '%')
  AND r.room_id = #{roomId}
  AND r.status = #{status}
  AND r.start_at >= #{dateFrom}
  AND r.start_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)

SELECT  FROM reservation
WHERE start_at >= #{from} AND start_at < #{to}
ORDER BY start_at, id
